-- FUNCTION: gbg_applicability_protect()
CREATE FUNCTION portal.gbg_applicability_protect() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO portal, pg_temp
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'applicability_determinations rows cannot be deleted (determination history is permanent)';
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.scope IS DISTINCT FROM OLD.scope
     OR NEW.asset_identity IS DISTINCT FROM OLD.asset_identity
     OR NEW.fleet_class IS DISTINCT FROM OLD.fleet_class
     OR NEW.decision_identity IS DISTINCT FROM OLD.decision_identity
     OR NEW.outcome IS DISTINCT FROM OLD.outcome
     OR NEW.basis IS DISTINCT FROM OLD.basis
     OR NEW.authority_reference IS DISTINCT FROM OLD.authority_reference
     OR NEW.ma_gate IS DISTINCT FROM OLD.ma_gate
     OR NEW.ma_revision IS DISTINCT FROM OLD.ma_revision
     OR NEW.confirmed_by IS DISTINCT FROM OLD.confirmed_by
     OR NEW.confirmed_by_name IS DISTINCT FROM OLD.confirmed_by_name
     OR NEW.confirmed_at IS DISTINCT FROM OLD.confirmed_at
  THEN
    RAISE EXCEPTION 'applicability_determinations rows are immutable: only supersession and invalidation may be recorded';
  END IF;

  -- Closing out is one-way.
  IF OLD.superseded_at IS NOT NULL AND NEW.superseded_at IS DISTINCT FROM OLD.superseded_at THEN
    RAISE EXCEPTION 'applicability_determinations: supersession cannot be changed once recorded';
  END IF;
  IF OLD.invalidated_at IS NOT NULL AND NEW.invalidated_at IS DISTINCT FROM OLD.invalidated_at THEN
    RAISE EXCEPTION 'applicability_determinations: invalidation cannot be changed once recorded';
  END IF;

  RETURN NEW;
END;
$$;

-- FUNCTION: gbg_applicability_reviewer_only()
CREATE FUNCTION portal.gbg_applicability_reviewer_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO portal, pg_temp
    AS $$
DECLARE
  is_reviewer boolean;
BEGIN
  SELECT applicability_reviewer INTO is_reviewer FROM staff_users WHERE id = NEW.confirmed_by;
  IF is_reviewer IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'applicability_determinations: % is not the Applicability Reviewer', NEW.confirmed_by_name;
  END IF;
  RETURN NEW;
END;
$$;

