-- FUNCTION: gbg_report_versions_protect()
CREATE FUNCTION portal.gbg_report_versions_protect() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO portal, pg_temp
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'report_versions rows cannot be deleted (version history is permanent)';
  END IF;
  IF OLD.status = 'draft' THEN
    RETURN NEW;
  END IF;
  -- OLD.status = 'locked': every column except the PDF artifact columns
  -- (pdf_object_key, pdf_bytes, pdf_generated_at) must be unchanged.
  IF ROW(NEW.id, NEW.job_id, NEW.version, NEW.snapshot_id, NEW.staff_model,
         NEW.client_model, NEW.staff_overlay, NEW.html_staff, NEW.html_client,
         NEW.status, NEW.created_at, NEW.locked_at, NEW.locked_by)
     IS DISTINCT FROM
     ROW(OLD.id, OLD.job_id, OLD.version, OLD.snapshot_id, OLD.staff_model,
         OLD.client_model, OLD.staff_overlay, OLD.html_staff, OLD.html_client,
         OLD.status, OLD.created_at, OLD.locked_at, OLD.locked_by) THEN
    RAISE EXCEPTION 'report_version % is locked: only the PDF columns (pdf_object_key, pdf_bytes, pdf_generated_at) may be backfilled', OLD.id;
  END IF;
  RETURN NEW;
END;
$$;


