-- TABLE: applicability_determinations
CREATE TABLE portal.applicability_determinations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    scope text NOT NULL,
    asset_identity text,
    fleet_class text,
    decision_identity text NOT NULL,
    outcome text NOT NULL,
    basis text NOT NULL,
    authority_reference text NOT NULL,
    ma_gate text NOT NULL,
    ma_revision text,
    confirmed_by uuid NOT NULL,
    confirmed_by_name text NOT NULL,
    confirmed_at timestamp with time zone DEFAULT now() NOT NULL,
    superseded_at timestamp with time zone,
    superseded_by uuid,
    invalidated_at timestamp with time zone,
    invalidated_reason text,
    CONSTRAINT applicability_basis_ck CHECK ((basis = ANY (ARRAY['GOVERNED'::text, 'INTERIM'::text]))),
    CONSTRAINT applicability_identity_ck CHECK ((((scope = 'asset'::text) AND (asset_identity IS NOT NULL) AND (fleet_class IS NULL)) OR ((scope = 'fleet'::text) AND (fleet_class IS NOT NULL) AND (asset_identity IS NULL)))),
    CONSTRAINT applicability_interim_revision_ck CHECK (((basis <> 'INTERIM'::text) OR (ma_revision IS NOT NULL))),
    CONSTRAINT applicability_invalidated_ck CHECK (((invalidated_at IS NULL) = (invalidated_reason IS NULL))),
    CONSTRAINT applicability_outcome_ck CHECK ((outcome = ANY (ARRAY['CONFIRMED NOT APPLICABLE'::text, 'CONFIRMED APPLICABLE'::text, 'UNDETERMINABLE'::text]))),
    CONSTRAINT applicability_scope_ck CHECK ((scope = ANY (ARRAY['asset'::text, 'fleet'::text])))
);

