-- TABLE: job_status_steps
CREATE TABLE portal.job_status_steps (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    step_key portal.job_step_key NOT NULL,
    state portal.job_step_state DEFAULT 'pending'::portal.job_step_state NOT NULL,
    checklist_key text,
    checklist_digest text,
    draft jsonb DEFAULT '{}'::jsonb NOT NULL,
    draft_revision integer DEFAULT 0 NOT NULL,
    last_saved_by uuid,
    last_saved_at timestamp with time zone,
    submitted jsonb,
    submitted_by uuid,
    submitted_at timestamp with time zone,
    push_state portal.job_step_push_state DEFAULT 'not_required'::portal.job_step_push_state NOT NULL,
    pushed_at timestamp with time zone,
    push_attempts integer DEFAULT 0 NOT NULL,
    push_error text,
    zuper_status_uid text,
    zuper_status_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT job_status_steps_push_accounted CHECK ((((push_state <> 'pushed'::portal.job_step_push_state) OR (pushed_at IS NOT NULL)) AND ((push_state <> 'failed'::portal.job_step_push_state) OR (push_error IS NOT NULL)))),
    CONSTRAINT job_status_steps_submitted_attributed CHECK (((state <> 'submitted'::portal.job_step_state) OR ((submitted IS NOT NULL) AND (submitted_by IS NOT NULL) AND (submitted_at IS NOT NULL))))
);

